data.query:
query Query($wo: WorkOrderWhereInput, $product: ProductWhereInput, $component: ProductWhereInput, $strategy: ProductStrategyWhereInput, $facility: FacilityWhereInput, $unit: UnitWhereInput, $wc: WorkcenterWhereInput) {
  wo: workOrder(where: $wo) {
    edges {
      node {
        id
        externalId
        workOrderStatusId
        processes: workOrderProcesses {
          edges {
            node {
              id
              boms: workOrderProcessBoms {
                edges {
                  node {
                    id
                  }
                }
              }
            }
          }
        }
      }
    }
  }
  product(where: $product) {
    edges {
      node {
        id
        externalId
        productTypeId
        active
        strategies(where: $strategy, first: 1) {
          edges {
            node {
              id
              active
              validated
              externalId
              strategyProcesses {
                edges {
                  node {
                    id
                  }
                }
              }
            }
          }
        }
      }
    }
  }
  component: product(where: $component) {
    edges {
      node {
        id
        externalId
        productTypeId
        strategies {
          edges {
            node {
              id
              externalId
              strategyProcesses(where: {final: {_eq: true}}, first: 1) {
                edges {
                  node {
                    id
                    externalId
                  }
                }
              }
            }
          }
        }
      }
    }
  }
  unit(where: $unit) {
    edges {
      node {
        id
      }
    }
  }
  facility(where: $facility) {
    edges {
      node {
        id
        externalId
      }
    }
  }
  workcenter(where: $wc) {
    edges {
      node {
        id
        externalId
      }
    }
  }
}

data.transform:
(
  $failP := $leftAntiJoin( 
    [$state.context.LOCAL.trx[0].l_item.{
      "id": $string($)
    }], 
    [product.edges.node[
      $not($isNilOrEmpty(strategies.edges.node.id))
    ]], 
    'id', 'externalId'
  );
    $failC := $leftAntiJoin( 
    [$state.context.LOCAL.trx[mc_item!=null].mc_item.{
      "id": $string($)
    }], 
    [component.edges.node[
      productTypeId in ["InvtPart", "NonInvtPart", "Assembly"] and $not($isNilOrEmpty(strategies.edges.node.strategyProcesses.edges.node))
      or  productTypeId in ["OthCharge"]
    ]], 
    'id', 'externalId'
  );

  $failU := $leftAntiJoin( [$state.context.LOCAL.trx.units[mainline='F'].{
    "id": $string($)
  }], [unit.edges.node], 'id', 'id');

   $failF := $leftAntiJoin( [$state.context.LOCAL.trx[mainline='T'].([location,transferlocation])].{
    "id": $string($)
  }, [facility.edges.node], 'id', 'externalId');

    $failW := $leftAntiJoin( [$uniq($state.context.LOCAL.trx[op_manufacturingworkcenter!=null].op_manufacturingworkcenter).{
    "id": $string($)
  }], [workcenter.edges.node], 'id', 'externalId');



  {
    "LOCAL": {
      "fztrx": wo.edges.node,
      "product": product.edges.node,
      "component": component.edges.node,
      "facility": facility.edges.node,
      "workcenter":workcenter.edges.node,
      "failP": $failP,
      "failU": $failU,
      "failF": $failF,
      "failC": $failC,
      "failW": $failW
    }
  } 

)

